import{_ as d,a0 as n,w as r,s as o,I as i,x as t,a1 as l,A as u,ao as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"有了新家的 Budgie 發佈了第一個新版本 | LCTT x X-CMD","titleTemplate":false,"description":"有了新家的 Budgie 發佈了第一個新版本 | LCTT (202203) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"有了新家的 Budgie 發佈了第一個新版本 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"有了新家的 Budgie 發佈了第一個新版本 | LCTT (202203) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202203/20220307 Budgie 10.6 is Here as its First Release Under the New Organization","title":"有了新家的 Budgie 發佈了第一個新版本","tag":"202203","desc":""},"relativePath":"202203/20220307 Budgie 10.6 is Here as its First Release Under the New Organization.md","filePath":"[post].md"}'),a={name:"202203/20220307 Budgie 10.6 is Here as its First Release Under the New Organization.md"};function g(m,e,f,b,B,w){const s=n("Link");return r(),o("div",null,[e[22]||(e[22]=i("h1",{id:"有了新家的-budgie-發佈了第一個新版本",tabindex:"-1"},[t("有了新家的 Budgie 發佈了第一個新版本 "),i("a",{class:"header-anchor",href:"#有了新家的-budgie-發佈了第一個新版本","aria-label":"Permalink to “有了新家的 Budgie 發佈了第一個新版本”"},"​")],-1)),e[23]||(e[23]=i("blockquote",null,[i("p",null,"在一個新組織的管理下， Budgie 10.6 發佈在一個新的倉庫，進行了一些令人印象深刻的改進。")],-1)),e[24]||(e[24]=i("p",null,[i("img",{src:"https://i0.wp.com/news.itsfoss.com/wp-content/uploads/2022/03/budgie-10-6-release.png?w=1200&ssl=1",alt:""})],-1)),e[25]||(e[25]=i("p",null,"早在今年一月份，Solus 的前聯合負責人 Joshua Strobl 在離開 Solus 後去 SerpentOS 工作的傳聞成為了新聞頭條。",-1)),i("p",null,[e[1]||(e[1]=t("你可以在我們的 ",-1)),l(s,{href:"https://news.itsfoss.com/solus-co-lead-resign-budgie-serpent/"},{default:u(()=>[...e[0]||(e[0]=[t("原始報道",-1)])]),_:1}),e[2]||(e[2]=t(" 中閲讀更多關於它的內容。",-1))]),e[26]||(e[26]=p('<p>然而，他仍然想為 Budgie 桌面環境工作，所以他（在一個新的倉庫中）復刻了這個項目，併成立了 Buddies Of Budgie 組織。三個月後，這個組織變化後的第一個版本已經到來，我們將在這裏看看它。</p><h3 id="budgie-10-6-的新變化" tabindex="-1">Budgie 10.6 的新變化 <a class="header-anchor" href="#budgie-10-6-的新變化" aria-label="Permalink to “Budgie 10.6 的新變化”">​</a></h3><p><img src="https://i0.wp.com/news.itsfoss.com/wp-content/uploads/2022/03/budgie-10.61.png?resize=1568%2C882&amp;ssl=1" alt=""></p><p>鑑於這是自上述組織結構調整後的第一個版本，它的功能變化相當少。儘管如此，這裏有一個關於新內容的總體總結：</p><ul><li>完善的主題設計</li><li>新的通知系統</li><li>代碼重新格式化</li></ul><p>在最新更新的公告中，Joshua 還提到：</p><blockquote><p>Budgie 10.6 旨在彌合 Budgie 傳統的“下游”消費者和開發組織本身之間的鴻溝，使像 Ubuntu Budgie 這樣的下游能夠更密切地參與到它的開發當中。</p><p>作為我們的核心支柱之一，即成為一個平台而不是一個產品，Budgie 10.6 和未來的 Budgie 版本的目標是提供一個宏觀世界，或一組最小的緊密耦合的組件，並將生態系統的其餘部分留給下游消費者的決策和價值觀，無論它是發行版還是終端用户。</p></blockquote><p>所以，如果你擔心 Budgie 桌面環境在分裂後的發展，這應該能讓你放心了。</p><h4 id="主題改進" tabindex="-1">主題改進 <a class="header-anchor" href="#主題改進" aria-label="Permalink to “主題改進”">​</a></h4><p><img src="https://i0.wp.com/news.itsfoss.com/wp-content/uploads/2022/03/budgie-10.6-theming.jpg?w=1159&amp;ssl=1" alt=""></p><p>看起來，這個版本的主題改進基本上是為了提高一致性，做一些細節的改變，以獲得現代的外觀。</p><p>例如，邊框圓角已經應用於一些桌面元素，統一的間距，統一的小工具的顏色方案，以及對 GTK 主題支持的其他改進。</p><p>從我對這個版本的親身體驗來看，這些變化是細微的，但也能讓人感受到，而且確實感覺到它們使 Budgie 更能與 GNOME 和 KDE 等桌面相提並論。</p><h4 id="新的通知系統" tabindex="-1">新的通知系統 <a class="header-anchor" href="#新的通知系統" aria-label="Permalink to “新的通知系統”">​</a></h4><p>雖然不是很明顯，但 Budgie 現在已經有了一個新的通知系統。其最大的影響是它現在已經從位於屏幕右側的面板 Raven 中移出。</p><p>因此，其他 Budgie 組件現在可以使用新的通知系統。一個提到的例子是“解鎖未來在圖標任務列表中支持通知徽章的能力”。</p><p>同樣，雖然此變化很小，但確實打開了未來的可能性，希望我們能在未來的版本中看到這些帶來的變化。</p><h4 id="其他改進措施" tabindex="-1">其他改進措施 <a class="header-anchor" href="#其他改進措施" aria-label="Permalink to “其他改進措施”">​</a></h4><p>Budgie 10.6 一些其他的變化包括：</p><ul><li>使用製表符而不是空格，對一些代碼進行了常規的重新格式化。</li><li>重新引入對 GNOME 40 的支持，以啓用 Ubuntu LTS 支持。</li><li>將 GNOME 控制中心重新命名為 Budgie 控制中心。</li><li>修復了擴大 Raven 縮略圖導致 Raven 本身調整大小的問題。</li></ul>',20)),i("p",null,[e[4]||(e[4]=t("如果你想了解更多，你可以在 ",-1)),l(s,{href:"https://github.com/BuddiesOfBudgie/budgie-desktop/releases/tag/v10.6"},{default:u(()=>[...e[3]||(e[3]=[t("GitHub",-1)])]),_:1}),e[5]||(e[5]=t(" 上找到發佈公告，以獲得完整的新功能列表。",-1))]),i("ul",null,[i("li",null,[l(s,{href:"https://github.com/BuddiesOfBudgie/budgie-desktop/releases/"},{default:u(()=>[...e[6]||(e[6]=[t("Budgie 10.6",-1)])]),_:1})])]),e[27]||(e[27]=i("h3",{id:"獲得-budgie-10-6",tabindex:"-1"},[t("獲得 Budgie 10.6 "),i("a",{class:"header-anchor",href:"#獲得-budgie-10-6","aria-label":"Permalink to “獲得 Budgie 10.6”"},"​")],-1)),e[28]||(e[28]=i("p",null,"如果你想獲得 Budgie 10.6，最好是先等待你的發行版將其打包。如果你使用的是 Arch，這可能需要不到一週的時間，而 Ubuntu 及其衍生版本則需要更長時間。",-1)),e[29]||(e[29]=i("p",null,"對於那些喜歡冒險的人來説，你也可以嘗試編譯它，但如果你願意嘗試，你可能已經知道如何做了。",-1)),e[30]||(e[30]=i("p",null,"總的來説，Budgie 10.6 看起來是一個值得關注的版本，特別是考慮到其重大的組織變化。",-1)),e[31]||(e[31]=i("p",null,"你對 Budgie 10.6 的變化有什麼看法？請在下面的評論中告訴我們吧！",-1)),e[32]||(e[32]=i("hr",null,null,-1)),i("p",null,[e[8]||(e[8]=t("via: ",-1)),l(s,{href:"https://news.itsfoss.com/budgie-10-6-release/"},{default:u(()=>[...e[7]||(e[7]=[t("https://news.itsfoss.com/budgie-10-6-release/",-1)])]),_:1})]),i("p",null,[e[13]||(e[13]=t("作者：",-1)),l(s,{href:"https://news.itsfoss.com/author/jacob/"},{default:u(()=>[...e[9]||(e[9]=[t("Jacob Crume",-1)])]),_:1}),e[14]||(e[14]=t(" 選題：",-1)),l(s,{href:"https://github.com/lujun9972"},{default:u(()=>[...e[10]||(e[10]=[t("lujun9972",-1)])]),_:1}),e[15]||(e[15]=t(" 譯者：",-1)),l(s,{href:"https://github.com/wxy"},{default:u(()=>[...e[11]||(e[11]=[t("wxy",-1)])]),_:1}),e[16]||(e[16]=t(" 校對：",-1)),l(s,{href:"https://github.com/wxy"},{default:u(()=>[...e[12]||(e[12]=[t("wxy",-1)])]),_:1})]),i("p",null,[e[19]||(e[19]=t("本文由 ",-1)),l(s,{href:"https://github.com/LCTT/TranslateProject"},{default:u(()=>[...e[17]||(e[17]=[t("LCTT",-1)])]),_:1}),e[20]||(e[20]=t(" 原創編譯，",-1)),l(s,{href:"https://linux.cn/"},{default:u(()=>[...e[18]||(e[18]=[t("Linux中國",-1)])]),_:1}),e[21]||(e[21]=t(" 榮譽推出",-1))])])}const k=d(a,[["render",g]]);export{C as __pageData,k as default};
